    /** A symbol's character and whether it is filled, or null if Gabarit does not know it. */
    fun glyph(symbol: String): Pair<Char, Boolean>? {
        val parts = symbol.split(".")
        val plain = parts.filter { it != "fill" }.joinToString(".")
        return characters[plain]?.let { it to (plain.length < symbol.length) }
    }
